      churn: demo && m.analytics && m.analytics.churnDemo != null ? m.analytics.churnDemo : (m.subscribers.length ? churn : 0),
      renewals: demo && renewals < 3 ? ((m.analytics && m.analytics.renewalsDemo) || renewals) : renewals,
