      month: [monthRev * 0.18, monthRev * 0.22, monthRev * 0.2, monthRev * 0.28, monthRev * 0.25, monthRev * 0.3, monthRev * 0.32].map(function (n) { return Math.max(20, Math.round((n || 80) / 10)); }),
